const sessions = new Map();

export function seedSession(id, value) { sessions.set(id, { ...value }); }
export function readSession(id) { return sessions.get(id); }
export async function updateSession(id, patch, release = Promise.resolve()) {
  const current = sessions.get(id) ?? {};
  await release;
  sessions.set(id, { ...current, ...patch });
  return sessions.get(id);
}

export function normalizeProfile(input) {
  const displayName = String(input.displayName ?? '').trim();
  return { displayName: displayName || 'Anonymous' };
}

export function clientHeaders() { return { 'x-client-version': 'v2' }; }
export function formatGreeting(name) { const x = String(name).trim(); return `Hello, ${x}`; }

