import assert from 'node:assert/strict';
import test from 'node:test';
import { clientHeaders, normalizeProfile, readSession, seedSession, updateSession } from '../src/app.mjs';

function deferred() { let resolve; const promise = new Promise((done) => { resolve = done; }); return { promise, resolve }; }

test('preserves independent concurrent session patches', async () => {
  seedSession('s1', { theme: 'light', locale: 'en' });
  const first = deferred();
  const second = deferred();
  const theme = updateSession('s1', { theme: 'dark' }, first.promise);
  const locale = updateSession('s1', { locale: 'ro' }, second.promise);
  first.resolve();
  second.resolve();
  await Promise.all([theme, locale]);
  assert.deepEqual(readSession('s1'), { theme: 'dark', locale: 'ro' });
});

test('trims a supplied display name', () => {
  assert.deepEqual(normalizeProfile({ displayName: ' Ada ' }), { displayName: 'Ada' });
});

test('sends the current client version', () => {
  assert.equal(clientHeaders()['x-client-version'], 'v1');
});
